// ratelimit_test.go
package ratelimit

import (
	"sync"
	"testing"
	"time"
)

// fakeClock is a manually advanced clock for deterministic tests.
type fakeClock struct {
	t time.Time
}

func (c *fakeClock) Now() time.Time { return c.t }
func (c *fakeClock) Advance(d time.Duration) {
	c.t = c.t.Add(d)
}

func newTestLimiter(t *testing.T, rate float64, burst int) (*Limiter, *fakeClock) {
	t.Helper()
	fc := &fakeClock{t: time.Unix(0, 0)}
	l, err := NewLimiter(rate, burst, fc)
	if err != nil {
		t.Fatalf("NewLimiter() error = %v", err)
	}
	return l, fc
}

func TestNewLimiterValidation(t *testing.T) {
	fc := &fakeClock{t: time.Unix(0, 0)}
	tests := []struct {
		name    string
		rate    float64
		burst   int
		clock   Clock
		wantErr error
	}{
		{"zero rate", 0, 1, fc, ErrNonPositiveRate},
		{"negative rate", -1.5, 1, fc, ErrNonPositiveRate},
		{"zero burst", 1, 0, fc, ErrNonPositiveBurst},
		{"negative burst", 1, -3, fc, ErrNonPositiveBurst},
		{"nil clock", 1, 1, nil, ErrNilClock},
		{"valid", 1, 1, fc, nil},
	}
	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			l, err := NewLimiter(tc.rate, tc.burst, tc.clock)
			if tc.wantErr != nil {
				if err != tc.wantErr {
					t.Fatalf("error = %v, want %v", err, tc.wantErr)
				}
				return
			}
			if err != nil {
				t.Fatalf("unexpected error: %v", err)
			}
			if l == nil {
				t.Fatal("limiter is nil")
			}
		})
	}
}

func TestAllowN(t *testing.T) {
	tests := []struct {
		name string
		rate float64
		burst int
		steps []struct {
			advance time.Duration
			n       int
			want    bool
		}
	}{
		{
			name: "burst exhausted immediately",
			rate: 1, burst: 2,
			steps: []struct {
				advance time.Duration
				n       int
				want    bool
			}{
				{0, 2, true},
				{0, 1, false},
			},
		},
		{
			name: "refill over time",
			rate: 1, burst: 2,
			steps: []struct {
				advance time.Duration
				n       int
				want    bool
			}{
				{0, 2, true},
				{time.Second, 1, true},
				{0, 1, false},
				{2 * time.Second, 2, true},
			},
		},
		{
			name: "tokens capped at burst",
			rate: 10, burst: 1,
			steps: []struct {
				advance time.Duration
				n       int
				want    bool
			}{
				{0, 1, true},
				{10 * time.Second, 1, true}, // only 1 token despite 100 accrued
				{0, 1, false},
			},
		},
		{
			name: "multi-token request",
			rate: 2, burst: 5,
			steps: []struct {
				advance time.Duration
				n       int
				want    bool
			}{
				{0, 3, true},
				{0, 3, false},
				{time.Second, 2, true},
				{0, 1, false},
			},
		},
		{
			name: "zero tokens always allowed",
			rate: 1, burst: 1,
			steps: []struct {
				advance time.Duration
				n       int
				want    bool
			}{
				{0, 0, true},
				{0, 1, true},
				{0, 0, true},
			},
		},
		{
			name: "negative request denied",
			rate: 1, burst: 1,
			steps: []struct {
				advance time.Duration
				n       int
				want    bool
			}{
				{0, -1, false},
				{0, 1, true},
			},
		},
	}
	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			l, fc := newTestLimiter(t, tc.rate, tc.burst)
			for i, s := range tc.steps {
				fc.Advance(s.advance)
				if got := l.AllowN(s.n); got != s.want {
					t.Fatalf("step %d: AllowN(%d) = %v, want %v", i, s.n, got, s.want)
				}
			}
		})
	}
}

func TestTokensRefill(t *testing.T) {
	l, fc := newTestLimiter(t, 2, 3)
	l.AllowN(3)
	if got := l.Tokens(); got != 0 {
		t.Fatalf("Tokens() = %v, want 0", got)
	}
	fc.Advance(500 * time.Millisecond)
	if got := l.Tokens(); got != 1 {
		t.Fatalf("Tokens() = %v, want 1", got)
	}
	fc.Advance(10 * time.Second)
	if got := l.Tokens(); got != 3 {
		t.Fatalf("Tokens() = %v, want 3 (capped at burst)", got)
	}
}

func TestConcurrentUse(t *testing.T) {
	l, _ := newTestLimiter(t, 1000, 100)
	var wg sync.WaitGroup
	allowed := make([]bool, 200)
	for i := 0; i < 200; i++ {
		wg.Add(1)
		go func(i int) {
			defer wg.Done()
			allowed[i] = l.Allow()
		}(i)
	}
	wg.Wait()
	var total int
	for _, ok := range allowed {
		if ok {
			total++
		}
	}
	if total != 100 {
		t.Fatalf("allowed %d tokens, want exactly 100 (burst)", total)
	}
}
